contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all test logic
    // depositAmount is the ether to send; caller is this contract
    function runTest(uint depositAmount) public {
        // ensure this contract has enough Ether to forward
        require(address(this).balance >= depositAmount);

        address caller = address(this);
        uint before = c.balances(caller);

        // perform the Deposit on c, sending Ether
        c.Deposit{value: depositAmount}();

        uint after = c.balances(caller);

        // The distinguishing property: balances increases by depositAmount
        assert(before + depositAmount == after);
    }

    // allow the test contract to receive Ether so it can forward deposits
    receive() external payable {}
}

