pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor, depositAmt, collector, collectAmt
    function testFuzz_property(address depositor, uint256 depositAmt, address collector, uint256 collectAmt) public {
        // keep addresses non-zero and distinct to be wide but valid
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));

        // bound amounts to reasonable ranges so we can fund EOAs and avoid overflow in balances
        depositAmt = bound(depositAmt, 0, 5 ether);
        collectAmt = bound(collectAmt, 0, 5 ether);

        // fund depositor and collector so they can send/receive
        vm.deal(depositor, depositAmt + 1 ether);
        vm.deal(collector, 1 ether);

        // depositor makes a deposit (via Deposit payable)
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // record balances mapping values for a chosen key (use depositor as key)
        uint256 before_depositor_balance = c.balances(depositor);
        uint256 before_collector_balance = c.balances(collector);

        // collector attempts to Collect(collectAmt)
        // we capture whether Collect succeeded (no revert) via try/catch
        bool ok;
        vm.prank(collector);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // After Collect returns, the reference implementation preserves that any account's stored
        // balance is never decreased as a result of the depositor's prior Deposit having been
        // incorrectly subtracted at deposit time; concretely we assert that for the depositor key,
        // the stored balance is >= 0 and equals the prior recorded mapping minus at most the collected
        // amount if the collector was the depositor and Collect succeeded. The single universal
        // assertion we can check via the contract's public surface is that if Collect succeeded and
        // collector==depositor then the new balance equals old minus collectAmt; otherwise the depositor's
        // stored balance is unchanged.
        // This property holds in the reference contract for all inputs but is violated by the mutant
        // that subtracts msg.value on Deposit (some inputs will make the balances differ).

        // compute expected per reference behavior:
        uint256 expected_after_depositor_balance = before_depositor_balance;
        if (ok && collector == depositor) {
            // only if collector is same account and had sufficient balance would Collect succeed
            // reference reduces by collectAmt
            expected_after_depositor_balance = before_depositor_balance >= collectAmt ? (before_depositor_balance - collectAmt) : before_depositor_balance;
        }

        // EXACTLY ONE assertion reading c's public getter
        assertTrue(c.balances(depositor) == expected_after_depositor_balance);
    }
}

