pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount, and collect amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // Keep depositAmt and collectAmt in reasonable ranges and non-zero where needed
        depositAmt = bound(depositAmt, 1, 10 ether);
        collectAmt = bound(collectAmt, 0, 10 ether);
        // Choose depositor non-zero
        vm.assume(depositor != address(0));

        // Ensure depositor has ETH to deposit
        vm.deal(depositor, depositAmt + 1 ether);

        // Make sure depositor's balance before actions
        uint256 before = c.balances(depositor);

        // Make a deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // After deposit reference should have increased by depositAmt (>= before)
        // But we don't assert intermediate here; we express final property after Collect

        // Ensure depositor meets MinSum so Collect can proceed in reference
        // If deposit alone doesn't reach MinSum, top up via another deposit call from depositor
        uint256 minSum = c.MinSum();
        if (c.balances(depositor) < minSum) {
            uint256 topUp = minSum - c.balances(depositor);
            // provide depositor enough funds
            vm.deal(depositor, topUp + 1);
            vm.prank(depositor);
            c.Deposit{value: topUp}();
        }

        uint256 balanceAfterDeposit = c.balances(depositor);

        // Bound collectAmt so that collectAmt <= balanceAfterDeposit to make Collect execute
        collectAmt = bound(collectAmt, 0, balanceAfterDeposit);

        // Call Collect from depositor and record success
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference: if collectAmt <= balanceAfterDeposit and balanceAfterDeposit >= MinSum,
        // Collect should succeed and leave stored balance equal to balanceAfterDeposit - collectAmt.
        // We assert that when Collect returned success, the stored balance equals expected value.
        if (ok) {
            uint256 finalBal = c.balances(depositor);
            assertTrue(finalBal == (balanceAfterDeposit - collectAmt));
        } else {
            // If Collect reverted, then reference also would revert under same admissible inputs; we do not assert further
            // but to satisfy the single-assert rule, assertTrue(true) is not allowed; so assert that ok == false implies the balances unchanged
            // However we must have exactly one assertTrue reading c; the above branch already covers ok==true case.
            // For ok==false we read c via public getter to satisfy single assertion requirement as follows:
            uint256 finalBal = c.balances(depositor);
            // When Collect failed, reference guarantees stored balance was not decreased by Collect; so finalBal == balanceAfterDeposit
            assertTrue(finalBal == balanceAfterDeposit);
        }
    }
}

