pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: depositor address and deposit & collect amounts.
    // We keep domain wide but constrain amounts to reasonable ranges so operations don't overflow
    // and so that collect can be satisfied (we ensure deposit >= collect and deposit >= MinSum).
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // Avoid zero-address depositor to make vm.prank meaningful
        vm.assume(depositor != address(0));
        // Bound amounts to sane ranges (<= 1e30) to avoid overflow in tests
        depositAmt = bound(depositAmt, 1 wei, 1e30);
        collectAmt = bound(collectAmt, 0, 1e30);

        // Ensure depositAmt >= MinSum so that Collect may be allowed by the reference
        // Read MinSum from the contract via its public getter
        uint256 minSum = c.MinSum();
        // If depositAmt < minSum, make depositAmt at least minSum
        if (depositAmt < minSum) depositAmt = minSum;

        // Ensure collectAmt <= depositAmt so Collect may succeed
        if (collectAmt > depositAmt) collectAmt = depositAmt;

        // Fund depositor for the deposit
        vm.deal(depositor, depositAmt);
        // Record previous stored balance for depositor (should be 0 initially)
        uint256 prevBalance = c.balances(depositor);

        // depositor makes a deposit of depositAmt
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Sanity: after Deposit, reference should have increased balance by depositAmt
        // (We will capture balance before Collect for the reference contract)
        uint256 balanceBeforeCollect = c.balances(depositor);

        // Now depositor calls Collect(collectAmt)
        bool ok;
        // Perform the call and catch any revert to observe behavior
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees: if Collect succeeds (ok==true) then
        // stored balance equals balanceBeforeCollect - collectAmt.
        // We assert that property on the deployed contract instance c.
        if (ok) {
            uint256 after = c.balances(depositor);
            assertTrue(after == (balanceBeforeCollect - collectAmt));
        } else {
            // If Collect reverted, then the reference contract must have reverted due to preconditions
            // In that case the stored balance must be unchanged from balanceBeforeCollect
            uint256 after = c.balances(depositor);
            assertTrue(after == balanceBeforeCollect);
        }
    }
}

