pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // keep amounts reasonable but wide
        depositAmt = bound(depositAmt, 0, 5 ether);
        collectAmt = bound(collectAmt, 0, 5 ether);

        // ensure depositor has funds to send
        vm.deal(depositor, depositAmt + 1 ether);

        // make depositor perform Deposit by sending ether
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // read balance before Collect for that depositor
        uint256 balBefore = c.balances(depositor);

        // ensure conditions for Collect: require bal >= MinSum and bal >= collectAmt
        // if balBefore < c.MinSum() or balBefore < collectAmt then Collect will do nothing; we only
        // consider the case where Collect can proceed. Skip otherwise.
        if (balBefore < c.MinSum() || balBefore < collectAmt) {
            // Nothing to assert about state change by Collect in this branch; assert that Collect is a no-op
            // i.e., after calling Collect the balance remains equal to balBefore.
            try c.Collect(collectAmt) {
                // call succeeded (maybe did nothing)
            } catch {
                // call reverted; still acceptable for reference but mutant may differ elsewhere
            }
            uint256 balAfter = c.balances(depositor);
            assertTrue(balAfter == balBefore);
            return;
        }

        // Now we have a scenario where Collect should proceed and send funds.
        // Call Collect as depositor
        vm.prank(depositor);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // If Collect succeeded, reference contract guarantees balAfter == balBefore - collectAmt
        if (ok) {
            uint256 balAfter = c.balances(depositor);
            assertTrue(balAfter == balBefore - collectAmt);
        } else {
            // If it reverted, then balance must be unchanged for the reference
            uint256 balAfter = c.balances(depositor);
            assertTrue(balAfter == balBefore);
        }
    }
}

