pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount, and collect amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // keep depositor non-zero and amounts reasonably bounded to avoid overflow and trivialities
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 1, 1 ether * 1000); // allow wide range but not astronomical
        collectAmt = bound(collectAmt, 0, 1 ether * 1000);

        // Arrange: fund depositor externally so they can Deposit
        vm.deal(depositor, depositAmt);

        // depositor makes a Deposit of depositAmt
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // read balance before Collect
        uint256 before = c.balances(depositor);

        // Only attempt Collect when before >= MinSum and collectAmt <= before
        // This captures the admissible domain where Collect would proceed on reference
        vm.assume(before >= c.MinSum());
        vm.assume(collectAmt <= before);

        // Let depositor call Collect(collectAmt). Capture whether it returned (succeeded) or reverted.
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: when Collect is admissible (before >= MinSum and collectAmt <= before)
        // it should succeed and leave balances[depositor] == before - collectAmt.
        // We assert that behavior on c (reference). The buggy mutant will for some inputs violate this
        // because deposits subtracted msg.value and change stored balances.
        assertTrue(ok && c.balances(depositor) == before - collectAmt);
    }
}
